tom = '20px';\n\t\t\telement.style.padding = '12px 6px';\n\t\t\telement.style.border = '1px solid #fff';\n\t\t\telement.style.borderRadius = '4px';\n\t\t\telement.style.background = 'rgba(0,0,0,0.1)';\n\t\t\telement.style.color = '#fff';\n\t\t\telement.style.font = 'normal 13px sans-serif';\n\t\t\telement.style.textAlign = 'center';\n\t\t\telement.style.opacity = '0.5';\n\t\t\telement.style.outline = 'none';\n\t\t\telement.style.zIndex = '999';\n\n\t\t}\n\n\t\tif ( 'xr' in navigator ) {\n\n\t\t\tbutton.id = 'ARButton';\n\t\t\tbutton.style.display = 'none';\n\n\t\t\tstylizeElement( button );\n\n\t\t\tnavigator.xr.isSessionSupported( 'immersive-ar' ).then( function ( supported ) {\n\n\t\t\t\tsupported ? showStartAR() : showARNotSupported();\n\n\t\t\t} ).catch( showARNotAllowed );\n\n\t\t\treturn button;\n\n\t\t} else {\n\n\t\t\tconst message = document.createElement( 'a' );\n\n\t\t\tif ( window.isSecureContext === false ) {\n\n\t\t\t\tmessage.href = document.location.href.replace( /^http:/, 'https:' );\n\t\t\t\tmessage.innerHTML = 'WEBXR NEEDS HTTPS'; // TODO Improve message\n\n\t\t\t} else {\n\n\t\t\t\tmessage.href = 'https://immersiveweb.dev/';\n\t\t\t\tmessage.innerHTML = 'WEBXR NOT AVAILABLE';\n\n\t\t\t}\n\n\t\t\tmessage.style.left = 'calc(50% - 90px)';\n\t\t\tmessage.style.width = '180px';\n\t\t\tmessage.style.textDecoration = 'none';\n\n\t\t\tstylizeElement( message );\n\n\t\t\treturn message;\n\n\t\t}\n\n\t}\n\n}\n\nexport { ARButton };\n"],"mappings":";AAAA,IAAM,WAAN,MAAe;CAEd,OAAO,aAAc,UAAU,cAAc,CAAC,GAAI;EAEjD,MAAM,SAAS,SAAS,cAAe,QAAS;EAEhD,SAAS,cAA0B;GAElC,IAAK,YAAY,eAAe,KAAA,GAAY;IAE3C,MAAM,UAAU,SAAS,cAAe,KAAM;IAC9C,QAAQ,MAAM,UAAU;IACxB,SAAS,KAAK,YAAa,OAAQ;IAEnC,MAAM,MAAM,SAAS,gBAAiB,8BAA8B,KAAM;IAC1E,IAAI,aAAc,SAAS,EAAG;IAC9B,IAAI,aAAc,UAAU,EAAG;IAC/B,IAAI,MAAM,WAAW;IACrB,IAAI,MAAM,QAAQ;IAClB,IAAI,MAAM,MAAM;IAChB,IAAI,iBAAkB,SAAS,WAAY;KAE1C,eAAe,IAAI;IAEpB,CAAE;IACF,QAAQ,YAAa,GAAI;IAEzB,MAAM,OAAO,SAAS,gBAAiB,8BAA8B,MAAO;IAC5E,KAAK,aAAc,KAAK,+BAAgC;IACxD,K